class Solution {
public:
    long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {
        const long long NEG = LLONG_MIN / 4;
        int n = nums1.size(), m = nums2.size();
        vector<vector<long long>> prev(m + 1, vector<long long>(k + 1, NEG));
        for (int j = 0; j <= m; ++j) prev[j][0] = 0;
        for (int i = 1; i <= n; ++i) {
            vector<vector<long long>> cur(m + 1, vector<long long>(k + 1, NEG));
            for (int j = 0; j <= m; ++j) cur[j][0] = 0;
            for (int j = 1; j <= m; ++j) {
                for (int t = 1; t <= k; ++t) {
                    cur[j][t] = max(prev[j][t], cur[j - 1][t]);
                    if (prev[j - 1][t - 1] != NEG)
                        cur[j][t] = max(cur[j][t], prev[j - 1][t - 1] +
                                        1LL * nums1[i - 1] * nums2[j - 1]);
                }
            }
            prev.swap(cur);
        }
        return prev[m][k];
    }
};
